contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address _newOwner) public {
        address oldOwner = c.owner();
        bool reverted;
        try c.transferOwnership(_newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (msg.sender == oldOwner) {
            assert(!reverted);
            assert(c.owner() == _newOwner);
        } else {
            assert(reverted);
            assert(c.owner() == oldOwner);
        }
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address _newOwner) public {
        address oldOwner = c.owner();
        bool reverted;
        try c.transferOwnership(_newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(!reverted && c.owner() == _newOwner || reverted && c.owner() == oldOwner);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newOwner) public {
        address initialOwner = c.owner();

        // Only proceed if caller is the current owner.
        require(msg.sender == initialOwner, "caller must be initial owner");

        // Perform the ownership transfer, expected to succeed.
        c.transferOwnership(newOwner);

        // Read the new owner through the public getter.
        address updatedOwner = c.owner();

        assert(updatedOwner == newOwner);
    }
}

